/* ===== Orchard — Design System ===== */
:root {
  --bg-primary: #f5f5f7;
  --bg-white: #ffffff;
  --text-primary: #1d1d1f;
  --text-secondary: #6e6e73;
  --text-tertiary: #86868b;
  --accent: #0066cc;
  --accent-hover: #004999;
  --border: #d2d2d7;
  --border-light: #e8e8ed;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.08);
  --radius-sm: 0.5rem;
  --radius: 1rem;
  --radius-lg: 1.25rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --nav-height: 48px;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-family: var(--font-stack);
  font-size: 17px;
  line-height: 1.47059;
  font-weight: 400;
  color: var(--text-primary);
  background: var(--bg-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s ease;
}
a:hover { color: var(--accent-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

/* ===== Typography ===== */
.headline-xl {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.015em;
}
.headline-lg {
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 700;
  line-height: 1.125;
  letter-spacing: -0.01em;
}
.headline-md {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.005em;
}
.headline-sm {
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.3;
}
.subhead {
  font-size: 1.125rem;
  font-weight: 400;
  color: var(--text-secondary);
  line-height: 1.4;
}
.caption {
  font-size: 0.75rem;
  color: var(--text-tertiary);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.price-lg {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-primary);
}
.price-sm {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

/* ===== Top Navigation ===== */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
  height: var(--nav-height);
}
.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.25rem;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.nav-brand {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 0.375rem;
}
.nav-brand:hover { text-decoration: none; color: var(--text-primary); }
.nav-brand .logo-dot {
  width: 8px; height: 8px;
  background: var(--accent);
  border-radius: 50%;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}
.nav-links a {
  padding: 0.375rem 0.75rem;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color 0.2s, background 0.2s;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: rgba(0,0,0,0.04);
  text-decoration: none;
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.nav-actions button {
  background: none;
  border: none;
  color: var(--text-primary);
  padding: 0.25rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== Ribbon Banner ===== */
.ribbon {
  background: #1d1d1f;
  color: #f5f5f7;
  text-align: center;
  padding: 0.625rem 1rem;
  font-size: 0.8125rem;
}
.ribbon a {
  color: #6db3f2;
  margin-left: 0.25rem;
}
.ribbon a:hover { color: #8dc4f6; }

/* ===== Hero Sections ===== */
.hero-section {
  text-align: center;
  padding: 3.5rem 1.25rem 2.5rem;
}
.hero-section .headline-xl {
  margin-bottom: 0.5rem;
}
.hero-section .subhead {
  margin-bottom: 1.5rem;
  font-size: 1.1875rem;
}
.hero-actions {
  display: flex;
  gap: 1.25rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  border-radius: var(--radius-full);
  border: none;
  transition: all 0.2s ease;
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover {
  background: var(--accent-hover);
  text-decoration: none;
}
.btn-outline {
  background: transparent;
  color: var(--accent);
  border: 1.5px solid var(--accent);
}
.btn-outline:hover {
  background: var(--accent);
  color: #fff;
  text-decoration: none;
}
.btn-plain {
  background: none;
  color: var(--accent);
  padding: 0;
  font-weight: 500;
}

/* ===== Product Icon Bar ===== */
.icon-bar-wrap {
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-white);
}
.icon-bar {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0.25rem 0;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-item {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  padding: 0.75rem 1.125rem;
  min-width: 80px;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-primary);
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: background 0.2s;
  scroll-snap-align: start;
}
.icon-bar-item:hover {
  background: rgba(0,0,0,0.03);
  text-decoration: none;
}
.icon-bar-icon {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--bg-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== Carousel ===== */
.carousel-container {
  position: relative;
  max-width: 1200px;
  margin: 0 auto;
}
.carousel-wrapper {
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  display: flex;
  gap: 1.25rem;
  padding: 0.5rem 1.25rem 1rem;
  scroll-behavior: smooth;
}
.carousel-wrapper::-webkit-scrollbar { display: none; }

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.2s ease;
  opacity: 0;
  pointer-events: none;
}
.carousel-container:hover .carousel-btn {
  opacity: 1;
  pointer-events: auto;
}
.carousel-btn:hover {
  background: #fff;
  box-shadow: var(--shadow-lg);
}
.carousel-btn:disabled {
  opacity: 0;
  pointer-events: none;
}
.carousel-btn-left { left: -6px; }
.carousel-btn-right { right: -6px; }

/* ===== Product Card ===== */
.product-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.product-card-image {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: var(--radius);
  background: var(--bg-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.product-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.product-card-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background: #1d1d1f;
  color: #f5f5f7;
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 0.2rem 0.5rem;
  border-radius: 3px;
  letter-spacing: 0.02em;
}
.product-card-badge.new {
  background: #ff3b30;
  color: #fff;
}
.color-dots {
  display: flex;
  gap: 0.375rem;
  align-items: center;
}
.color-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  border: 1px solid rgba(0,0,0,0.15);
}
.product-card-title {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.25;
}
.product-card-tagline {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.35;
}
.product-card-price {
  font-size: 0.9375rem;
  font-weight: 600;
}
.product-card-monthly {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ===== Section ===== */
.section {
  padding: 3rem 1.25rem;
}
.section-header {
  text-align: center;
  margin-bottom: 2rem;
}
.section-header .headline-md {
  margin-bottom: 0.375rem;
}
.section-header .subhead {
  max-width: 560px;
  margin: 0 auto;
}
.section-light {
  background: var(--bg-primary);
}

/* ===== Homepage Product Grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));
  gap: 1.25rem;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.25rem 3rem;
}
.product-hero-tile {
  position: relative;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s, transform 0.3s;
  display: flex;
  flex-direction: column;
  min-height: 440px;
  cursor: pointer;
}
.product-hero-tile:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.product-hero-tile-header {
  padding: 2rem 2rem 0;
  text-align: center;
  z-index: 1;
}
.product-hero-tile-header h3 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.375rem;
  letter-spacing: -0.005em;
}
.product-hero-tile-header p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}
.product-hero-tile-image {
  flex: 1;
  background: var(--bg-primary);
  margin: 1rem;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.product-hero-tile-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.product-hero-tile-actions {
  padding: 0 2rem 2rem;
  display: flex;
  gap: 1.25rem;
  justify-content: center;
}
/* Gradient tile backgrounds */
.tile-gradient-phone { background: linear-gradient(135deg, #f5f0eb 0%, #e8e0d5 100%); }
.tile-gradient-laptop { background: linear-gradient(135deg, #e8edf2 0%, #d5dce3 100%); }
.tile-gradient-tablet { background: linear-gradient(135deg, #f0eef5 0%, #e2dceb 100%); }
.tile-gradient-earbuds { background: linear-gradient(135deg, #ebf0f1 0%, #d8e2e5 100%); }
.tile-gradient-trade { background: linear-gradient(135deg, #e3f0f5 0%, #cce0e8 100%); }

/* ===== Entertainment Tabs ===== */
.ent-tabs-nav {
  display: flex;
  justify-content: center;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}
.ent-tab-btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: none;
  border: none;
  border-radius: var(--radius-full);
  transition: all 0.2s ease;
}
.ent-tab-btn:hover { color: var(--text-primary); background: rgba(0,0,0,0.04); }
.ent-tab-btn.active {
  background: #1d1d1f;
  color: #fff;
}
.ent-tab-panel {
  display: none;
}
.ent-tab-panel.active {
  display: block;
}
.ent-card-row {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  padding: 0.5rem 0 1rem;
  scrollbar-width: none;
}
.ent-card-row::-webkit-scrollbar { display: none; }
.ent-card {
  flex: 0 0 260px;
  border-radius: var(--radius);
  overflow: hidden;
  background: #1d1d1f;
  color: #fff;
  transition: transform 0.3s;
}
.ent-card:hover { transform: scale(1.02); }
.ent-card-image {
  aspect-ratio: 16 / 10;
  background: #2d2d2f;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.ent-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ent-card-body {
  padding: 1rem;
}
.ent-card-body h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}
.ent-card-body p {
  font-size: 0.8125rem;
  color: #a1a1aa;
  margin-bottom: 0.75rem;
}

/* ===== Help / Store Difference Cards ===== */
.help-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s, transform 0.3s;
}
.help-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.help-card-icon {
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.75rem;
  color: var(--accent);
}
.help-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}
.help-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* ===== Brand Collab ===== */
.brand-collab {
  text-align: center;
  padding: 3rem 1.25rem;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: #fff;
  border-radius: var(--radius-xl);
  max-width: 1200px;
  margin: 0 auto;
}
.brand-collab .subhead {
  color: rgba(255,255,255,0.7);
}
.brand-logos {
  display: flex;
  gap: 2rem;
  justify-content: center;
  align-items: center;
  margin: 1.5rem 0;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brand-logos span {
  opacity: 0.8;
}
.brand-collab-products {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}
.brand-product-pill {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.1);
  font-size: 0.875rem;
  color: rgba(255,255,255,0.9);
}

/* ===== Quick Links ===== */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.25rem 2rem;
}
.quick-link {
  padding: 0.625rem 1.25rem;
  background: var(--bg-primary);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: all 0.2s;
}
.quick-link:hover {
  background: #e8e8ed;
  text-decoration: none;
  color: var(--text-primary);
}

/* ===== Sticky Section Nav (Category Pages) ===== */
.section-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 999;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
}
.section-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 0.125rem;
  padding: 0 1rem;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav-link {
  flex: 0 0 auto;
  padding: 0.75rem 1rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
}
.section-nav-link:hover,
.section-nav-link.active {
  color: var(--text-primary);
  border-bottom-color: var(--text-primary);
  text-decoration: none;
}

/* ===== Category Hero ===== */
.category-hero {
  text-align: center;
  padding: 2.5rem 1.25rem 1.5rem;
  background: var(--bg-primary);
}
.category-hero .headline-lg {
  margin-bottom: 0.5rem;
}

/* ===== Shopping Guide Cards ===== */
.guide-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s, transform 0.3s;
  text-align: center;
  cursor: pointer;
}
.guide-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.guide-card-icon {
  width: 48px; height: 48px;
  margin: 0 auto 1rem;
  background: var(--bg-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
}
.guide-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}
.guide-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ===== Finance Banner ===== */
.finance-banner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
  background: linear-gradient(135deg, #f8f9fa 0%, #f0f0f5 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.finance-banner-icon {
  width: 48px; height: 48px;
  background: #1d1d1f;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  flex-shrink: 0;
}
.finance-banner-text h4 {
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: 0.125rem;
}
.finance-banner-text p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ===== Footer ===== */
.footer {
  background: var(--bg-primary);
  padding: 2.5rem 1.25rem 1.5rem;
  margin-top: auto;
}
.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 2rem 1.5rem;
}
.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 0.625rem;
  color: var(--text-primary);
}
.footer-col a {
  display: block;
  font-size: 0.75rem;
  color: var(--text-secondary);
  padding: 0.2rem 0;
}
.footer-col a:hover {
  color: var(--text-primary);
  text-decoration: underline;
}
.footer-bottom {
  max-width: 1200px;
  margin: 2rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-light);
}
.footer-legal {
  font-size: 0.6875rem;
  color: var(--text-tertiary);
  line-height: 1.5;
}
.footer-legal p {
  margin-bottom: 0.5rem;
}
.footer-copyright {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 1rem;
}

/* ===== Mobile Footer Accordion ===== */
@media (max-width: 767px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col {
    border-bottom: 1px solid var(--border-light);
  }
