  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.finance-banner-icon {
  width: 48px; height: 48px;
  background: #1d1d1f;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  flex-shrink: 0;
}
.finance-banner-text h4 {
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: 0.125rem;
}
.finance-banner-text p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ===== Footer ===== */
.footer {
  background: var(--bg-primary);
  padding: 2.5rem 1.25rem 1.5rem;
  margin-top: auto;
}
.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 2rem 1.5rem;
}
.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 0.625rem;
  color: var(--text-primary);
}
.footer-col a {
  display: block;
  font-size: 0.75rem;
  color: var(--text-secondary);
  padding: 0.2rem 0;
}
.footer-col a:hover {
  color: var(--text-primary);
  text-decoration: underline;
}
.footer-bottom {
  max-width: 1200px;
  margin: 2rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-light);
}
.footer-legal {
  font-size: 0.6875rem;
  color: var(--text-tertiary);
  line-height: 1.5;
}
.footer-legal p {
  margin-bottom: 0.5rem;
}
.footer-copyright {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 1rem;
}

/* ===== Mobile Footer Accordion ===== */
@media (max-width: 767px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col {
    border-bottom: 1px solid var(--border-light);
  }
  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    margin-bottom: 0;
    font-size: 0.875rem;
    user-select: none;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 1.25rem;
    font-weight: 400;
    color: var(--text-tertiary);
    transition: transform 0.3s;
  }
  .footer-col.open h4::after {
    content: '−';
  }
  .footer-links {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
  }
  .footer-col.open .footer-links {
    max-height: 600px;
    padding-bottom: 0.75rem;
  }
  .footer-col .footer-links a {
    padding: 0.375rem 0;
  }

  /* Mobile carousel buttons always visible */
  .carousel-btn {
    opacity: 0.85;
    pointer-events: auto;
  }
  .carousel-btn-left { left: 0; }
  .carousel-btn-right { right: 0; }

  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-card {
    flex: 0 0 240px;
  }
  .product-hero-tile {
    min-height: 380px;
  }
  .hero-actions {
    flex-direction: column;
    align-items: center;
  }
}

/* ===== Animations ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  animation: fadeInUp 0.5s ease-out both;
}

/* ===== Utility ===== */
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 1.25rem; }
